import ctypes, ctypes.util
lib = ctypes.CDLL("/usr/lib/aarch64-linux-gnu/libzstd.so.1")
lib.ZSTD_compressBound.restype = ctypes.c_size_t
lib.ZSTD_compressBound.argtypes = [ctypes.c_size_t]
lib.ZSTD_createCCtx.restype = ctypes.c_void_p
lib.ZSTD_freeCCtx.argtypes = [ctypes.c_void_p]
lib.ZSTD_CCtx_setParameter.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_int]
lib.ZSTD_CCtx_setParameter.restype = ctypes.c_size_t
lib.ZSTD_compress2.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p, ctypes.c_size_t]
lib.ZSTD_compress2.restype = ctypes.c_size_t
lib.ZSTD_isError.argtypes = [ctypes.c_size_t]
lib.ZSTD_isError.restype = ctypes.c_uint
lib.ZSTD_getErrorName.argtypes = [ctypes.c_size_t]
lib.ZSTD_getErrorName.restype = ctypes.c_char_p
lib.ZSTD_decompress.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p, ctypes.c_size_t]
lib.ZSTD_decompress.restype = ctypes.c_size_t
class InBuf(ctypes.Structure):
    _fields_ = [("src", ctypes.c_void_p), ("size", ctypes.c_size_t), ("pos", ctypes.c_size_t)]
class OutBuf(ctypes.Structure):
    _fields_ = [("dst", ctypes.c_void_p), ("size", ctypes.c_size_t), ("pos", ctypes.c_size_t)]
lib.ZSTD_compressStream2.argtypes = [ctypes.c_void_p, ctypes.POINTER(OutBuf), ctypes.POINTER(InBuf), ctypes.c_int]
lib.ZSTD_compressStream2.restype = ctypes.c_size_t
lib.ZSTD_CCtx_refPrefix.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_size_t]
lib.ZSTD_CCtx_refPrefix.restype = ctypes.c_size_t

def compress(data, params=None, chunks=None):
    """params: dict param->value. chunks: list of chunk sizes for streaming with flush between."""
    cctx = lib.ZSTD_createCCtx()
    for k, v in (params or {}).items():
        r = lib.ZSTD_CCtx_setParameter(cctx, k, v)
        if lib.ZSTD_isError(r): raise Exception(lib.ZSTD_getErrorName(r))
    cap = lib.ZSTD_compressBound(len(data)) + 1024 * (1 + len(chunks or []))
    dst = ctypes.create_string_buffer(cap)
    src = ctypes.create_string_buffer(bytes(data), len(data) + 1)
    if chunks is None:
        r = lib.ZSTD_compress2(cctx, dst, cap, src, len(data))
        if lib.ZSTD_isError(r): raise Exception(lib.ZSTD_getErrorName(r))
        lib.ZSTD_freeCCtx(cctx)
        return dst.raw[:r]
    out = OutBuf(ctypes.cast(dst, ctypes.c_void_p), cap, 0)
    pos = 0
    for i, c in enumerate(chunks + [len(data)]):
        end = min(len(data), pos + c) if i < len(chunks) else len(data)
        inb = InBuf(ctypes.cast(src, ctypes.c_void_p).value + pos, end - pos, 0)
        mode = 1 if i < len(chunks) else 2  # flush / end
        while True:
            r = lib.ZSTD_compressStream2(cctx, ctypes.byref(out), ctypes.byref(inb), mode)
            if lib.ZSTD_isError(r): raise Exception(lib.ZSTD_getErrorName(r))
            if r == 0 and inb.pos == inb.size: break
        pos = end
    lib.ZSTD_freeCCtx(cctx)
    return dst.raw[:out.pos]
